import json, sys
c = json.load(open("captions.json"))
W = c if isinstance(c, list) else c.get("words", c.get("captions", []))
qs = sys.argv[1:]
for q in qs:
    ql = q.lower().split()
    for i in range(len(W) - len(ql) + 1):
        ok = True
        for k, qw in enumerate(ql):
            wt = W[i+k]["text"].strip().lower().strip(".,!?\"'()")
            if wt != qw:
                ok = False
                break
        if ok:
            print("%8.1fs - %8.1fs   %s" % (W[i]["startMs"]/1000.0, W[i+len(ql)-1]["endMs"]/1000.0, q))

# -*- coding: utf-8 -*-
import json
F = json.load(open("pedidos/_todos.json"))
for k in ("p001_a", "p001_b", "p001_c"):
    F.pop(k, None)
have = {"p027", "p076", "p106", "p118", "p001"}
ids = []
for x in json.load(open("planos.json")):
    i = x["id"]
    if i in F and i not in have and not i.startswith("s0"):
        ids.append(i)
print(len(ids), ids)
lotes = [ids[:40], ids[40:80]]
for n, L in enumerate(lotes, 2):
    json.dump([F[i] for i in L], open("pedidos/lote0%d.json" % n, "w"), ensure_ascii=False, indent=1)
    print("lote0%d" % n, len(L))

